# -- Write the investment register into the spreadsheet in SharePoint --
import base64
import re
from datetime import date

from openpyxl import Workbook, load_workbook
from openpyxl.styles import Alignment, Font, PatternFill
from openpyxl.utils import get_column_letter

SPW = "m365-sharepoint-write"
FOLDER = "Investments/Reports"
SHEET = "MySMB"
GAPS_SHEET = "Gaps and queries"
HEADERS = ["Investor entity", "Investment into", "Asset type", "Asset", "Commitment", "Unfunded commitment",
           "First investment", "Term", "Holding period", "Tax status", "Liquidity", "Currency", "Website",
           "General", "The business", "The investment", "Notes", "Folder"]
WIDTHS = [30, 34, 12, 40, 14, 16, 14, 20, 14, 16, 34, 20, 26, 14, 52, 52, 70, 38]
# Values a person has typed into the register are never overwritten by what AI reads next run.
KEEP = ["Asset type", "Asset", "Commitment", "Unfunded commitment", "First investment", "Term", "Tax status",
        "Liquidity", "Currency", "Website", "General", "The business", "The investment", "Notes"]
HEAD_FILL = "1F3864"
MONTHS = ["", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def _err(exc):
    msg = str(exc)
    if msg.startswith("tool_error: "):
        msg = msg[len("tool_error: "):]
    if "no usable credential" in msg or "credential unavailable" in msg:
        return ("the connection that writes to SharePoint needs connecting (Settings - Connections - "
                "m365-sharepoint-write)")
    return msg[:300]


def _norm(s):
    return re.sub(r"[^a-z0-9]", "", str(s or "").lower())


def _key(entity, folder):
    return _norm(entity) + "|" + _norm(folder)


def _d_fmt(d):
    return str(d.day).zfill(2) + "-" + MONTHS[d.month] + "-" + str(d.year)[2:]


def _esc(s):
    return str(s or "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _cell_text(v):
    if v is None:
        return ""
    if isinstance(v, date):
        return str(v.day).zfill(2) + "/" + str(v.month).zfill(2) + "/" + str(v.year)
    return str(v).strip()


def _style_header(ws, widths):
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor=HEAD_FILL)
        c.alignment = Alignment(vertical="center")
    for i, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(i)].width = w
    for line in ws.iter_rows(min_row=2):
        for c in line:
            c.alignment = Alignment(vertical="top", wrap_text=True)
    ws.freeze_panes = "A2"


rows = params.get("rows") or []
gaps = params.get("gaps") or []
top_name = str(params.get("top_name") or "")
problem = str(params.get("problem") or "")
link = str(params.get("register_link") or "").strip()
today = date.today()

register_file = ""
report_link = ""
kept = 0
added = 0
updated = 0
was_rows = 0
backed_up = ""
trouble = ""

# -- The workbook as it stands --------------------------------------------------------------------------
wb = None
item = {}
if link and rows:
    try:
        got = api.connectors.invoke(server=SPW, tool="read_sharepoint_file_bytes", args={"url": link})
        got = got if isinstance(got, dict) else {}
        item = got.get("file") or {}
        raw = base64.b64decode(str(got.get("content_base64") or ""))
        path = api.files.scratch_path("register_in.xlsx")
        with open(path, "wb") as fh:
            fh.write(raw)
        wb = load_workbook(path)
    except Exception as exc:
        trouble = "Couldn't open the register in SharePoint: " + _err(exc)
elif not link:
    trouble = ("No register link: paste the link of the spreadsheet to populate (Share - Copy link) when you "
               "click Run now.")

if wb is not None:
    ws = wb[SHEET] if SHEET in wb.sheetnames else (wb.worksheets[0] if wb.worksheets else wb.create_sheet(SHEET))
    # The headings as the spreadsheet writes them, so a column it already has is filled rather than repeated.
    head = [_cell_text(c.value) for c in ws[1]] if ws.max_row >= 1 else []
    at = {}
    for i, name in enumerate(head):
        if _norm(name) and _norm(name) not in at:
            at[_norm(name)] = i + 1
    width = len(head)
    for name in HEADERS:
        if _norm(name) not in at:
            width += 1
            at[_norm(name)] = width
            ws.cell(row=1, column=width, value=name)

    # -- What is already in it ---------------------------------------------------------------------------
    held = {}
    alone = {}
    where_row = {}
    for r in range(2, ws.max_row + 1):
        was = {}
        for name in HEADERS:
            was[name] = _cell_text(ws.cell(row=r, column=at[_norm(name)]).value)
        if not (was.get("Investor entity") or was.get("Folder")):
            continue
        was_rows += 1
        # Indexed under the folder name AND the investment name. A register kept by hand has no Folder
        # column in it yet, so matching on the folder alone would treat every row a person had already
        # filled in as a row that never existed, and write straight over it.
        for other in (was.get("Folder"), was.get("Investment into")):
            if other:
                if _key(was.get("Investor entity"), other) not in held:
                    held[_key(was.get("Investor entity"), other)] = was
                    where_row[_key(was.get("Investor entity"), other)] = r
                alone.setdefault(_norm(other), []).append((was, r))

    # -- Fill it in --------------------------------------------------------------------------------------
    next_row = ws.max_row + 1
    for row in rows:
        at_row = None
        was = None
        for other in (row.get("_folder"), row.get("Investment into")):
            k = _key(row.get("Investor entity"), other)
            if k in held:
                was, at_row = held[k], where_row[k]
                break
        # Last resort: the entity is written differently on the two sides - "Rapaki Pty Ltd ATF Rapaki Share
        # Trust" against the folder it sits in - and the folder name belongs to one row only.
        if was is None:
            for other in (row.get("_folder"), row.get("Investment into")):
                near = alone.get(_norm(other)) or []
                if len(near) == 1:
                    was, at_row = near[0]
                    break
        if at_row is None:
            at_row = next_row
            next_row += 1
            added += 1
        else:
            updated += 1
        for name in HEADERS:
            fresh = str(row.get("_folder") or "") if name == "Folder" else str(row.get(name) or "")
            mine = (was or {}).get(name) or ""
            if mine and name in KEEP:
                if mine.strip() != fresh.strip():
                    kept += 1
                continue
            if fresh:
                ws.cell(row=at_row, column=at[_norm(name)], value=fresh)
    _style_header(ws, WIDTHS[:max(len(WIDTHS), width)] + [24] * max(0, width - len(WIDTHS)))

    # -- The gaps behind it ------------------------------------------------------------------------------
    if GAPS_SHEET in wb.sheetnames:
        del wb[GAPS_SHEET]
    gs = wb.create_sheet(GAPS_SHEET)
    gs.append(["Folder or file", "What was found", "What to do about it"])
    for g in gaps:
        gs.append([str(x or "") for x in (list(g) + ["", "", ""])[:3]])
    _style_header(gs, [46, 76, 66])

    out = api.files.scratch_path("register_out.xlsx")
    wb.save(out)
    with open(out, "rb") as fh:
        data = fh.read()

    # A dated copy beside it before it is replaced, because this writes the whole file. Same name within a
    # day, so a run repeated through the morning leaves one copy and not six.
    base = re.sub(r"\.xlsx$", "", str(item.get("name") or "Register"), flags=re.I)
    if item.get("parentId") and item.get("driveId"):
        try:
            api.connectors.invoke(server=SPW, tool="write_sharepoint_file",
                                  args={"drive_id": item["driveId"], "item_id": item["parentId"],
                                        "file_name": base + " (before " + _d_fmt(today) + ").xlsx",
                                        "content_base64": base64.b64encode(raw).decode("ascii")})
            backed_up = base + " (before " + _d_fmt(today) + ").xlsx"
        except Exception as exc:
            trouble = ("Couldn't save a copy of the register before changing it (" + _err(exc) + "), so it "
                       "was left alone.")

    if not trouble:
        try:
            wrote = api.connectors.invoke(server=SPW, tool="write_sharepoint_file",
                                          args={"url": link,
                                                "content_base64": base64.b64encode(data).decode("ascii")})
            wrote = wrote if isinstance(wrote, dict) else {}
            register_file = str((wrote.get("file") or {}).get("webUrl") or link)
        except Exception as exc:
            trouble = "Couldn't write the register back to SharePoint: " + _err(exc)

    # Knowledge keeps a copy of exactly what went up, so there is a record even when SharePoint refuses.
    try:
        api.files.put(file=FOLDER + "/" + base + " " + _d_fmt(today) + ".xlsx", scratch_file=out)
    except Exception:
        pass

entities = []
for row in rows:
    if row.get("Investor entity") and row["Investor entity"] not in entities:
        entities.append(row["Investor entity"])

# Reports shows HTML, not spreadsheets, so the register goes up there as a page people can read without
# opening Excel. The spreadsheet in SharePoint stays the one that is kept.
name = (top_name or "Investments") + " Investment Register " + _d_fmt(today)
head_cells = "".join("<th>" + _esc(h) + "</th>" for h in HEADERS[:9])
body_rows = ""
for row in rows:
    body_rows += "<tr>" + "".join("<td>" + _esc(row.get(h)) + "</td>" for h in HEADERS[:9]) + "</tr>"
gap_rows = "".join("<tr><td>" + _esc(g[0]) + "</td><td>" + _esc(g[1] if len(g) > 1 else "") + "</td><td>" +
                   _esc(g[2] if len(g) > 2 else "") + "</td></tr>" for g in gaps)
page_html = (
    "<!doctype html><html><head><meta charset=\"utf-8\"><title>" + _esc(name) + "</title><style>"
    "body{font-family:Segoe UI,Arial,sans-serif;color:#1b1b1b;margin:24px;}"
    "h1{font-size:20px;margin:0 0 4px;}h2{font-size:15px;margin:24px 0 8px;}"
    "p.sub{color:#555;margin:0 0 16px;font-size:13px;}"
    "table{border-collapse:collapse;width:100%;font-size:12px;}"
    "th{background:#1F3864;color:#fff;text-align:left;padding:6px 8px;font-weight:600;}"
    "td{border-bottom:1px solid #e3e3e3;padding:6px 8px;vertical-align:top;}"
    "</style></head><body><h1>" + _esc(name) + "</h1><p class=\"sub\">" +
    str(len(rows)) + " investments across " + str(len(entities)) + " entities, read from " + _esc(top_name) +
    ". The spreadsheet itself is in SharePoint.</p>"
    "<table><tr>" + head_cells + "</tr>" + body_rows + "</table>"
    "<h2>Gaps and queries (" + str(len(gaps)) + ")</h2>"
    "<table><tr><th>Folder or file</th><th>What was found</th><th>What to do about it</th></tr>" +
    gap_rows + "</table></body></html>")
html_path = api.files.scratch_path("register.html")
with open(html_path, "w", encoding="utf-8") as fh:
    fh.write(page_html)
try:
    made = api.artifacts.put(title=name, scratch_file=html_path, file_name=name + ".html", kind="document",
                             visibility="tenant", mime_type="text/html",
                             description="Every investment held across " + str(len(entities)) +
                             " entities, read from the SharePoint folders.",
                             tags=["investment register", (top_name or "Investments")[:40]])
    report_link = str((made or {}).get("url") or "") if isinstance(made, dict) else ""
except Exception:
    report_link = ""

if problem and not rows:
    summary = problem
elif trouble:
    summary = trouble
else:
    summary = ("Filled in " + str(updated) + " row" + ("" if updated == 1 else "s") + " and added " +
               str(added) + " in the register in SharePoint, across " + str(len(entities)) + " entities. " +
               str(kept) + " cell" + ("" if kept == 1 else "s") + " already filled in by hand " +
               ("was" if kept == 1 else "were") + " left as " + ("it" if kept == 1 else "they") + " stood. " +
               str(len(gaps)) + " gaps and queries are on the " + GAPS_SHEET + " sheet." +
               ((" A copy of it as it was is beside it as \"" + backed_up + "\".") if backed_up else ""))
